## API Route Template

```typescript
// routes/{{resourceName}}.ts
import { Router } from 'express';
import { {{ResourceName}}Service } from '../services/{{resourceName}}';

const router = Router();

router.get('/{{resourcePath}}', async (req, res) => {
  const items = await {{ResourceName}}Service.findAll();
